def control(obs):
    global t0
    if t0 is None: t0=obs['t']
    dt=obs['t']-t0
    h=obs['hitch_deg']
    if dt<3.0:
        return (15.0,1.2,170)
    if dt<5.0:
        return (0.0,0.0,-64)
    rear=obs['rig']['trailer_rear']
    th=math.radians(-h)
    cx=rear[0]+1.2*math.sin(th); cy=rear[1]-1.2*math.cos(th)
    best=9.0
    for k,v in (obs.get('views') or {}).items():
        o=v['origin']
        for b,d in v['walls']:
            x=o[0]+d*math.cos(math.radians(b)); y=o[1]+d*math.sin(math.radians(b))
            if y<cy+0.5 and abs(x-cx)<3.0:
                best=min(best,math.hypot(x-cx,y-cy))
    cov=obs['progress']['covered']
    des=12.0 if cov<14 else 5.0
    st=max(-45,min(45,1.5*(h-des)))
    if best<0.4:
        print('close',best)
        return (st,0.0,-64)
    return (st,-0.6,-64)

